const baseline = $input.first().json.measure;
const schedule = $('Get Due Schedules1').first().json;

// Tracking object for performance monitoring
const tracking = {
  user_id: schedule.user_id,
  interval_days: schedule.interval_days || 7,
  processed_at: new Date().toISOString(),
  status: 'calculated'
};

if (!baseline) {
  return [{ json: { ...tracking, status: 'skipped', reason: 'No sensor data' } }];
}

const minVal = Math.round(baseline * (1 + 0.01 * schedule.trigger_percentage));
const maxVal = minVal + 20;

return [{
  json: {
    ...tracking,
    minValue: minVal,
    maxValue: maxVal,
    type: schedule.usecase_name,
    usecase_id: schedule.usecase_id,
    user_id: schedule.user_id,
    active: true
  }
}];

const items = $input.all();

if (items.length === 0 || !items[0].json.userid) {
  return [{
    json: {
      statusCode: 404,
      success: false,
      error: "User or monitoring type not found"
    }
  }];
}

const result = items[0].json;

return [{
  json: {
    statusCode: 200,
    success: true,
    userId: result.userid,
    monitoringType: result.monitoringType,
    usecaseId: result.usecaseId
  }
}];

