const raw = $input.first().json.query;

const userIdRaw = raw.userId;
const userFname = raw.firstName ?? "";
const userLname = raw.lastName ?? "";

if (!userIdRaw) {
  throw new Error("Missing required 'userId' parameter.");
}

const userId = Number(userIdRaw);
if (!Number.isFinite(userId)) {
  throw new Error("'userId' must be a valid numeric identifier.");
}

return [{
  json: {
    statusCode: 200,
    userId,
    userFname, 
    userLname
  }
}];

const body = $input.first().json.body ?? {};

const userId = body.userId;
const smartWatchId = body.smartWatchId;
const androidId = body.androidId;
const monitoringType = body.monitoringType;
const timestamp = body.timestamp;
const reasonHead = body.reason;
const bluetoothStatus = body.bluetoothStatus;
const n8nStatus = body.n8nStatus;
const locationStatus = body.locationStatus;


let reasonBody;

switch (reasonHead) {
  case "user_stopped":
    reasonBody = "notification stop button pressed";
    break;

  case "service_destroyed":
    reasonBody = "Android/app killed the service";
    break;

  case "max_n8n_retries":
    reasonBody = "n8n config connection failed too many times";
    break;

  default:
    reasonBody = `Unknown reason: ${reasonHead}`;
    break;
}


return [{
  JSON: {
    userId,
    smartWatchId,
    androidId,
    monitoringType,
    timestamp,
    reasonHead,
    reasonBody,
    bluetoothStatus,
    n8nStatus,
    locationStatus
  }
}];

const body = $input.first().json.body ?? {};
const allowed = new Set(['assign_mapping_to_user', 'change', 'duplicate_mapping_for_user']);
const action = String(body.action ?? '').trim();

if (!allowed.has(action)) {
  return [{ json: { valid: false, statusCode: 400, success: false, message: 'Unsupported mapping command action.' } }];
}

const params = typeof body.params === 'string'
  ? JSON.parse(body.params)
  : { ...(body.params ?? {}) };

if (action === 'assign_mapping_to_user') {
  params.id = Number(body.mapping_id ?? body.feedback_config_rule_id ?? params.id ?? params.mapping_id);
  params.mapping_id = params.id;
  params.user_id = Number(body.user_id ?? params.user_id);
} else if (action === 'duplicate_mapping_for_user') {
  params.id = Number(body.original_mapping_id ?? params.id ?? params.mapping_id);
  params.mapping_id = params.id;
  params.user_id = Number(body.user_id ?? params.user_id);
}

const missing = [];
if (!Number(body.usecase_id)) missing.push('usecase_id');
if (!String(body.usecase_name ?? '').trim()) missing.push('usecase_name');
if (action === 'assign_mapping_to_user' && (!params.id || !params.user_id)) missing.push('mapping_id/user_id');
if (action === 'duplicate_mapping_for_user' && (!params.id || !params.user_id)) missing.push('original_mapping_id/user_id');

if (missing.length > 0) {
  return [{ json: { valid: false, statusCode: 400, success: false, message: 'Missing required field(s): ' + missing.join(', ') } }];
}

return [{
  json: {
    valid: true,
    statusCode: 200,
    success: true,
    action: action === 'assign_mapping_to_user' ? 'assign' : action,
    params,
    usecase_id: Number(body.usecase_id),
    usecase_name: String(body.usecase_name).trim(),
    session_id: body.session_id ?? 'mapping-commands',
    message: body.message ?? ''
  }
}];

const result = $input.first().json ?? {};
const reply = result.reply ?? result.message ?? '';
const failed = result.success === false || /could not|did not work|issue|missing|invalid/i.test(reply);

return [{
  json: {
    statusCode: failed ? 500 : 200,
    success: !failed,
    message: reply || (failed ? 'Mapping command failed.' : 'Mapping command completed.'),
    data: result
  }
}];
